import java.util.*;class TaskBinding{static Object count(String[]codes){return Audit.count(codes);}static Set<String>unique(Object result){Set<String>out=new HashSet<>();for(CodeKey key:((Audit.Result)result).unique())out.add(key.code());return out;}static Map<String,Integer>counts(Object result){Map<String,Integer>out=new HashMap<>();for(var e:((Audit.Result)result).counts().entrySet())out.put(e.getKey().code(),e.getValue());return out;}static Integer lookup(Object result,String code){return ((Audit.Result)result).counts().get(new CodeKey(code));}static boolean equal(String a,String b){return new CodeKey(a).equals(new CodeKey(b));}static int hash(String a){return new CodeKey(a).hashCode();}}
